private async Task InitializeCompletionSchemaAsync(SqliteConnection c,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText=CompletionSchema;await q.ExecuteNonQueryAsync(ct);}
public async Task<bool> GenerateCompletionDesignAsync(string runId,string reservoir,CompletionDesignOptions o,ReservoirCompletionClient client,CancellationToken ct=default){LogObservationArtifact log=await GetLogObservationBatchAsync(runId,ct)??throw new RunStageFailureException("LogObservationMissing","S5 log missing.");if(log.ObservationModelVersion!=LogObservationOptions.CurrentModelVersion)throw new PersistenceIntegrityException("S6 requires a verified synthetic-petrophysics-v2 log artifact.");RunResponse run=await GetRunAsync(runId,ct)??throw new RunStageFailureException("RunMissing","Run missing.");TruthBindingResponse binding=await GetBindingAsync(run.ScenarioId,ct)??throw new RunStageFailureException("BindingMissing","Binding missing.");var openings=ObservableCompletionDesigner.Generate(runId,reservoir,log,o);var metadata=await client.BindAsync(binding,log,openings,o,ct);string oj=CanonicalJson.Serialize(o),oh=DeterministicIdentity.Sha256(oj),input=CanonicalJson.Serialize(new{runId,scenarioId=run.ScenarioId,logObservationBatchId=log.ObservationBatchId,logObservationHash=log.OutputHash,reservoirName=reservoir,optionsHash=oh}),ih=DeterministicIdentity.Sha256(input),opens=CanonicalJson.Serialize(openings),openHash=DeterministicIdentity.Sha256(opens),meta=CanonicalJson.Serialize(metadata),metaHash=DeterministicIdentity.Sha256(meta),id=DeterministicIdentity.Create("completion-design-v1",runId,ih,openHash,metaHash);await using var c=await OpenAsync(ct);await using var tx=c.BeginTransaction(false);RunResponse current=await ReadRunAsync(c,tx,runId,ct)??throw new RunStageFailureException("RunMissing","Run missing.");if((await ReadStagesAsync(c,tx,runId,ct)).Single(x=>x.Stage==RunStageKind.S5GenerateLogs).Status!=StageStatus.Completed)throw new RunStageFailureException("IllegalStageProgression","S5 incomplete.");if(await ReadCompletionDesignAsync(c,tx,runId,ct)is not null){await tx.CommitAsync(ct);return false;}DateTimeOffset now=timeProvider.GetUtcNow();await using var q=Command(c,tx,"INSERT INTO CompletionDesigns VALUES($id,$run,$scenario,$log,$logHash,$reservoir,$model,$calibration,$options,$optionsHash,$input,$inputHash,$openings,$openHash,$metadata,$metaHash,$status,$created);");object[] values=["$id",id,"$run",runId,"$scenario",run.ScenarioId,"$log",log.ObservationBatchId,"$logHash",log.OutputHash,"$reservoir",reservoir,"$model",o.ModelVersion,"$calibration",o.CalibrationVersion,"$options",oj,"$optionsHash",oh,"$input",input,"$inputHash",ih,"$openings",opens,"$openHash",openHash,"$metadata",meta,"$metaHash",metaHash,"$status","Draft","$created",Format(now)];for(int i=0;i<values.Length;i+=2)Add(q,(string)values[i],values[i+1]);await q.ExecuteNonQueryAsync(ct);string summary=CanonicalJson.Serialize(new{completionDesignId=id,completionBindingId=metadata.CompletionBindingId,designHash=ih,openingsHash=openHash,openingCount=metadata.OpeningCount,producingConnectionCount=metadata.ProducingConnectionCount,modelVersion=o.ModelVersion,status="Draft"});var audit=await AppendAuditAsync(c,tx,current.ScenarioId,"completion.design-created",id,summary,ct);await using var stage=Command(c,tx,"UPDATE RunStages SET InputJson=$input,InputHash=$ih,OutputJson=$output,OutputHash=$oh,AttemptCount=AttemptCount+1,Status=$status,StartedUtc=COALESCE(StartedUtc,$now),EndedUtc=NULL,Diagnostics=NULL,PreviousAuditHash=$previous WHERE RunId=$run AND Stage=$stage;");Add(stage,"$input",input);Add(stage,"$ih",ih);Add(stage,"$output",summary);Add(stage,"$oh",DeterministicIdentity.Sha256(summary));Add(stage,"$status",StageStatus.AwaitingApproval.ToString());Add(stage,"$now",Format(now));Add(stage,"$previous",audit.PreviousHash);Add(stage,"$run",runId);Add(stage,"$stage",(int)RunStageKind.S6DesignCompletion);await stage.ExecuteNonQueryAsync(ct);await UpdateRunAsync(c,tx,runId,RunStatus.AwaitingApproval,RunStageKind.S6DesignCompletion,now,null,null,ct);await tx.CommitAsync(ct);return true;}
public Task<ApiOutcome> ApproveCompletionAsync(
    string route, string key, string runId, string actor, CancellationToken ct = default,
    string? reviewedOpeningsHash = null)
{
    // Keep the canonical request byte-identical for existing internal callers and stored replays.
    string canonical = reviewedOpeningsHash is null
        ? CanonicalJson.Serialize(new { runId, actor })
        : CanonicalJson.Serialize(new { runId, actor, reviewedOpeningsHash });
    return ExecuteIdempotentAsync(route, key, canonical, async (c, tx, t) =>
    {
        if (string.IsNullOrWhiteSpace(actor) || actor.Length > 100 || actor.Any(char.IsControl))
            return Problem(400, "A bounded X-DrillSim-Human-Actor header is required");
        if (reviewedOpeningsHash is not null && !CompletionReview.IsValidHash(reviewedOpeningsHash))
            return Problem(400, "A reviewed lowercase openings SHA-256 hash is required");
        RunResponse? run = await ReadRunAsync(c, tx, runId, t);
        if (run is null) return Problem(404, "Run not found");
        CompletionDesign? d = await ReadCompletionDesignAsync(c, tx, runId, t);
        if (d is null) return Problem(409, "Completion design missing");
        if (d.RunId != run.RunId || d.ScenarioId != run.ScenarioId)
            throw new PersistenceIntegrityException("Completion approval identity mismatch.");
        if (reviewedOpeningsHash is not null && reviewedOpeningsHash != d.OpeningsHash)
            return Problem(409, "Reviewed completion openings hash does not match the immutable design");
        await using (var find = Command(c, tx, "SELECT Actor FROM CompletionApprovals WHERE CompletionDesignId=$id;"))
        {
            Add(find, "$id", d.CompletionDesignId);
            if (await find.ExecuteScalarAsync(t) is string old)
                return old == actor
                    ? Json(200, new { completionDesignId = d.CompletionDesignId, status = "Approved", modelVersion = d.ModelVersion })
                    : Problem(409, "Completion approved by a different actor");
        }
        if (run.Status != RunStatus.AwaitingApproval || run.CurrentStage != RunStageKind.S6DesignCompletion ||
            (await ReadStagesAsync(c, tx, runId, t)).Single(x => x.Stage == RunStageKind.S6DesignCompletion).Status != StageStatus.AwaitingApproval)
            return Problem(409, "Run is not awaiting completion approval at S6");
        DateTimeOffset now = timeProvider.GetUtcNow();
        string aid = DeterministicIdentity.Create("completion-approval-v1", d.CompletionDesignId, actor);
        await using var ins = Command(c, tx, "INSERT INTO CompletionApprovals VALUES($id,$design,$actor,$time);");
        Add(ins, "$id", aid); Add(ins, "$design", d.CompletionDesignId); Add(ins, "$actor", actor); Add(ins, "$time", Format(now));
        await ins.ExecuteNonQueryAsync(t);
        string summary = CanonicalJson.Serialize(new
        {
            completionDesignId = d.CompletionDesignId, completionBindingId = d.BindingMetadata.CompletionBindingId,
            designHash = d.ObservableInputHash, openingsHash = d.OpeningsHash,
            openingCount = d.BindingMetadata.OpeningCount, producingConnectionCount = d.BindingMetadata.ProducingConnectionCount,
            modelVersion = d.ModelVersion, status = "Approved"
        });
        await AppendAuditAsync(c, tx, run.ScenarioId, "completion.approved", d.CompletionDesignId,
            CanonicalJson.Serialize(new { approvalId = aid, actor, status = "Approved" }), t);
        var audit = await AppendAuditAsync(c, tx, run.ScenarioId, "stage.completed", runId,
            CanonicalJson.Serialize(new { stage = RunStageKind.S6DesignCompletion, commitmentHash = d.OpeningsHash }), t);
        await using var stage = Command(c, tx,
            "UPDATE RunStages SET OutputJson=$output,OutputHash=$hash,Status=$status,EndedUtc=$time,Diagnostics=NULL,PreviousAuditHash=$previous WHERE RunId=$run AND Stage=$stage AND Status=$awaiting;");
        Add(stage, "$output", summary); Add(stage, "$hash", DeterministicIdentity.Sha256(summary));
        Add(stage, "$status", StageStatus.Completed.ToString()); Add(stage, "$time", Format(now));
        Add(stage, "$previous", audit.PreviousHash); Add(stage, "$run", runId);
        Add(stage, "$stage", (int)RunStageKind.S6DesignCompletion); Add(stage, "$awaiting", StageStatus.AwaitingApproval.ToString());
        if (await stage.ExecuteNonQueryAsync(t) != 1)
            throw new PersistenceIntegrityException("Completion approval stage changed within its transaction.");
        await UpdateRunAsync(c, tx, runId, RunStatus.Queued, RunStageKind.S6DesignCompletion, now, null, null, t);
        return Json(202, new { completionDesignId = d.CompletionDesignId, status = "Approved", modelVersion = d.ModelVersion },
            $"/drillingoperations/api/runs/{runId}");
    }, ct);
}
