)!=expectedInput||r.GetString(16)!="Draft"||CanonicalJson.Serialize(validatedOptions)!=r.GetString(8)||validatedOptions.ModelVersion!=r.GetString(6)||validatedOptions.CalibrationVersion!=r.GetString(7)||meta.ScenarioId.ToString("D")!=r.GetString(2)||meta.RunId.ToString("D")!=runId||meta.ModelVersion!=r.GetString(6)||meta.WorldId!=r.GetString(21)||meta.CanonicalRequestHash!=DeterministicIdentity.Sha256(stageRequest)||r.GetString(0)!=expected||r.GetString(4)!=r.GetString(20)||r.GetString(9)!=opt||r.GetString(11)!=ih||r.GetString(13)!=oh||r.GetString(15)!=mh||CanonicalJson.Serialize(openings)!=r.GetString(12)||CanonicalJson.Serialize(meta)!=r.GetString(14)||meta.OpeningCount!=openings.Length)throw new PersistenceIntegrityException("Completion design integrity failure.");bool approved=!r.IsDBNull(18);return new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),r.GetString(8),r.GetString(9),r.GetString(10),r.GetString(11),openings,r.GetString(13),meta,r.GetString(15),approved?"Approved":"Draft",Parse(r.GetString(17)),approved?Parse(r.GetString(18)):null,approved?r.GetString(19):null);}
private const string CompletionSchema="""CREATE TABLE IF NOT EXISTS CompletionDesigns(CompletionDesignId TEXT PRIMARY KEY,RunId TEXT NOT NULL UNIQUE,ScenarioId TEXT NOT NULL,LogObservationBatchId TEXT NOT NULL,LogObservationHash TEXT NOT NULL,ReservoirName TEXT NOT NULL,ModelVersion TEXT NOT NULL,CalibrationVersion TEXT NOT NULL,CanonicalOptionsJson TEXT NOT NULL,OptionsHash TEXT NOT NULL,CanonicalObservableInputJson TEXT NOT NULL,ObservableInputHash TEXT NOT NULL,OpeningsJson TEXT NOT NULL,OpeningsHash TEXT NOT NULL,BindingMetadataJson TEXT NOT NULL,BindingMetadataHash TEXT NOT NULL,Status TEXT NOT NULL,CreatedUtc TEXT NOT NULL,FOREIGN KEY(RunId)REFERENCES Runs(RunId),FOREIGN KEY(LogObservationBatchId)REFERENCES ObservationBatches(ObservationBatchId));CREATE TABLE IF NOT EXISTS CompletionApprovals(ApprovalId TEXT PRIMARY KEY,CompletionDesignId TEXT NOT NULL UNIQUE,Actor TEXT NOT NULL,ApprovedUtc TEXT NOT NULL,FOREIGN KEY(CompletionDesignId)REFERENCES CompletionDesigns(CompletionDesignId));CREATE TRIGGER IF NOT EXISTS TR_CompletionDesigns_NoUpdate BEFORE UPDATE ON CompletionDesigns BEGIN SELECT RAISE(ABORT,"Completion designs are immutable");END;CREATE TRIGGER IF NOT EXISTS TR_CompletionDesigns_NoDelete BEFORE DELETE ON CompletionDesigns BEGIN SELECT RAISE(ABORT,"Completion designs are immutable");END;CREATE TRIGGER IF NOT EXISTS TR_CompletionApprovals_NoUpdate BEFORE UPDATE ON CompletionApprovals BEGIN SELECT RAISE(ABORT,"Completion approvals are immutable");END;CREATE TRIGGER IF NOT EXISTS TR_CompletionApprovals_NoDelete BEFORE DELETE ON CompletionApprovals BEGIN SELECT RAISE(ABORT,"Completion approvals are immutable");END;""";}


